-- create "acting_profiles" table
CREATE TABLE "acting_profiles" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "account_id" uuid NOT NULL, "profile_id" uuid NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "actingprofile_account_id" to table: "acting_profiles"
CREATE UNIQUE INDEX "actingprofile_account_id" ON "acting_profiles" ("account_id");
-- create "business_categories" table
CREATE TABLE "business_categories" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "parent_id" uuid NULL, "name" character varying NOT NULL, "slug" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'active', "created_by_account_id" uuid NULL, PRIMARY KEY ("id"));
-- create index "businesscategory_parent_id" to table: "business_categories"
CREATE INDEX "businesscategory_parent_id" ON "business_categories" ("parent_id");
-- create index "businesscategory_slug" to table: "business_categories"
CREATE UNIQUE INDEX "businesscategory_slug" ON "business_categories" ("slug");
-- create "outbox_events" table
CREATE TABLE "outbox_events" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "event_type" character varying NOT NULL, "subject" character varying NOT NULL, "payload" jsonb NOT NULL, "published_at" timestamptz NULL, PRIMARY KEY ("id"));
-- create index "outboxevent_published_at_created_at" to table: "outbox_events"
CREATE INDEX "outboxevent_published_at_created_at" ON "outbox_events" ("published_at", "created_at");
-- create "reserved_username_rules" table
CREATE TABLE "reserved_username_rules" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "term" character varying NOT NULL, "match_kind" character varying NOT NULL, "created_by" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- create index "reservedusernamerule_term_match_kind" to table: "reserved_username_rules"
CREATE UNIQUE INDEX "reservedusernamerule_term_match_kind" ON "reserved_username_rules" ("term", "match_kind");
-- create "username_changes" table
CREATE TABLE "username_changes" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "previous_username" character varying NOT NULL, "new_username" character varying NOT NULL, "reason" character varying NOT NULL, PRIMARY KEY ("id"));
-- create index "usernamechange_account_id_created_at" to table: "username_changes"
CREATE INDEX "usernamechange_account_id_created_at" ON "username_changes" ("account_id", "created_at");
-- create "username_holds" table
CREATE TABLE "username_holds" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "username" character varying NOT NULL, "kind" character varying NOT NULL, "held_for_account_id" uuid NULL, "reason" character varying NOT NULL DEFAULT '', "note" character varying NOT NULL DEFAULT '', "created_by" character varying NOT NULL DEFAULT '', "expires_at" timestamptz NULL, PRIMARY KEY ("id"));
-- create index "usernamehold_username" to table: "username_holds"
CREATE UNIQUE INDEX "usernamehold_username" ON "username_holds" ("username");
-- create "profiles" table
CREATE TABLE "profiles" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "account_id" uuid NOT NULL, "kind" character varying NOT NULL, "handle" character varying NOT NULL, "display_name" character varying NOT NULL DEFAULT '', "bio" character varying NOT NULL DEFAULT '', "website" character varying NULL, "avatar_media_key" character varying NULL, "avatar_url" character varying NULL, "banner_media_key" character varying NULL, "banner_url" character varying NULL, "is_private" boolean NOT NULL DEFAULT false, "country_code" character varying NULL, "verified" boolean NOT NULL DEFAULT false, "status" character varying NOT NULL DEFAULT 'active', "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "profile_account_id" to table: "profiles"
CREATE INDEX "profile_account_id" ON "profiles" ("account_id");
-- create index "profile_handle" to table: "profiles"
CREATE UNIQUE INDEX "profile_handle" ON "profiles" ("handle");
-- create index "profile_one_creator_per_account" to table: "profiles"
CREATE UNIQUE INDEX "profile_one_creator_per_account" ON "profiles" ("account_id") WHERE ((kind)::text = 'creator'::text);
-- create index "profile_one_personal_per_account" to table: "profiles"
CREATE UNIQUE INDEX "profile_one_personal_per_account" ON "profiles" ("account_id") WHERE ((kind)::text = 'personal'::text);
-- create "profile_categories" table
CREATE TABLE "profile_categories" ("profile_id" uuid NOT NULL, "business_category_id" uuid NOT NULL, PRIMARY KEY ("profile_id", "business_category_id"), CONSTRAINT "profile_categories_business_category_id" FOREIGN KEY ("business_category_id") REFERENCES "business_categories" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "profile_categories_profile_id" FOREIGN KEY ("profile_id") REFERENCES "profiles" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
